/**
 * セトリの曲名と Discography 楽曲を相互参照するためのマッチング層。
 *
 * - シート側の表記揺れを吸収して `songId` を解決する。
 * - 完全一致 → 副題ストリップ → 正規化 → エイリアス辞書 の順で照合する。
 * - 「代表 songId」は同一表記の中で最も古い (= 最小 songId) を採用する。
 */

import { Song } from "../types/discography";
import { SONG_ALIASES } from "../data/songAliases";

/** Unicode 正規化 + 小文字化 + 余白/記号除去 */
export const normalizeSongName = (s: string | null | undefined): string => {
  if (!s) return "";
  return s
    .normalize("NFKC")
    .toLowerCase()
    .replace(/[\s()（）\[\]【】「」『』!?！？/／・,，.。\-_~〜]+/g, "");
};

/** 副題などの括弧書きを除去 */
export const stripParenthetical = (s: string | null | undefined): string => {
  if (!s) return "";
  return s.replace(/\s*[（(].*?[)）]\s*/g, "").trim();
};

export interface SongIndex {
  byExact: Map<string, number>;
  byStripped: Map<string, number>;
  byNormalized: Map<string, number>;
}

/** Discography 楽曲一覧から照合用インデックスを構築する。 */
export const buildSongIndex = (songs: Song[]): SongIndex => {
  const byExact = new Map<string, number>();
  const byStripped = new Map<string, number>();
  const byNormalized = new Map<string, number>();

  // 代表 songId は最小値（最古のリリース）を採用する
  const sorted = [...songs].sort((a, b) => a.songId - b.songId);
  for (const s of sorted) {
    const name = s.songName;
    if (!name) continue;
    if (!byExact.has(name)) byExact.set(name, s.songId);
    const stripped = stripParenthetical(name);
    if (stripped && !byStripped.has(stripped)) byStripped.set(stripped, s.songId);
    const norm = normalizeSongName(name);
    if (norm && !byNormalized.has(norm)) byNormalized.set(norm, s.songId);
  }
  return { byExact, byStripped, byNormalized };
};

export type MatchSource =
  | "exact"
  | "alias"
  | "stripped"
  | "normalized"
  | "stripped+normalized"
  | "none";

export interface MatchResult {
  songId: number | null;
  source: MatchSource;
}

/** セトリ表記から songId を解決する */
export const matchSongId = (
  setlistName: string | null | undefined,
  index: SongIndex
): MatchResult => {
  if (!setlistName) return { songId: null, source: "none" };

  // 1) 完全一致
  const exact = index.byExact.get(setlistName);
  if (exact !== undefined) return { songId: exact, source: "exact" };

  // 2) 手動 alias 辞書
  const aliased = SONG_ALIASES[setlistName];
  if (aliased !== undefined) return { songId: aliased, source: "alias" };

  // 3) 副題ストリップで一致
  const stripped = stripParenthetical(setlistName);
  if (stripped) {
    const s = index.byExact.get(stripped) ?? index.byStripped.get(stripped);
    if (s !== undefined) return { songId: s, source: "stripped" };
  }

  // 4) 正規化で一致
  const norm = normalizeSongName(setlistName);
  if (norm) {
    const s = index.byNormalized.get(norm);
    if (s !== undefined) return { songId: s, source: "normalized" };
  }

  // 5) ストリップ + 正規化
  if (stripped) {
    const ns = normalizeSongName(stripped);
    if (ns) {
      const s = index.byNormalized.get(ns);
      if (s !== undefined) return { songId: s, source: "stripped+normalized" };
    }
  }

  return { songId: null, source: "none" };
};
